import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"WAF — enumerated source for the Azure VMware Solution workload assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-avs-workload-checklist.md","filePath":"frameworks/waf-avs-workload-checklist.md"}'),i={name:"frameworks/waf-avs-workload-checklist.md"};function n(s,e,d,c,l,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="waf-—-enumerated-source-for-the-azure-vmware-solution-workload-assessment" tabindex="-1">WAF — enumerated source for the Azure VMware Solution workload assessment <a class="header-anchor" href="#waf-—-enumerated-source-for-the-azure-vmware-solution-workload-assessment" aria-label="Permalink to &quot;WAF — enumerated source for the Azure VMware Solution workload assessment&quot;">​</a></h1><p><strong>Enumerated 2026-08-01. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>The audit&#39;s DQ12 records why this file exists: <em>&quot;Writing rules against a framework you have not enumerated is how <code>waf.storage.yaml</code> happened&quot;</em> — a rule file scoring a WAF pillar that does not exist. A future <code>waf.avs.yaml</code> is written against this enumeration and nothing else, and every rule in it must cite an item number from the tables below.</p><h2 id="what-this-assessment-is-and-what-it-turned-out-not-to-be" tabindex="-1">What this assessment is, and what it turned out not to be <a class="header-anchor" href="#what-this-assessment-is-and-what-it-turned-out-not-to-be" aria-label="Permalink to &quot;What this assessment is, and what it turned out not to be&quot;">​</a></h2><p>Microsoft ships an <strong>&quot;Azure VMware Solution Well-Architected Assessment Tool&quot;</strong> (announced in the AVS &quot;What&#39;s new&quot; for August 2023, pointing to <code>https://aka.ms/avswafdocs</code>) — §14, item 6 of <code>pmo/audits/AZURE-SCOUT-AUDIT.md</code> names this as a target. Verification for this file attempted to locate a published, five-pillar WAF service guide for AVS analogous to the Azure Local one (<code>azure/well-architected/service-guides/azure-local</code>).</p><p><strong>No such page exists at the time of this enumeration.</strong> Two things were tried and both came back negative:</p><ol><li>A direct fetch of <code>https://learn.microsoft.com/en-us/azure/well-architected/azure-vmware/overview</code> — the URL the AVS reliability page itself links to for &quot;production deployment recommendations&quot; — <strong>resolved to the generic &quot;Azure Well-Architected Framework workloads&quot; landing page</strong>, not an AVS-specific service guide. This is the same link-rot pattern documented for the AVD checklist in this release and flagged generally in the audit&#39;s §8 currency warnings.</li><li>A Microsoft Learn documentation search for &quot;Architecture best practices for Azure VMware Solution&quot; (the naming pattern every other WAF service guide in this batch uses) returned no matching page.</li></ol><p>So, unlike the other three checklists in this release, <strong>there is no single Microsoft-published WAF pillar checklist for AVS to transcribe.</strong> What follows is not a fabrication of one — it&#39;s an honest build from the closest genuinely published, structured content: the AVS <strong>Reliability</strong> pillar guide (which does exist, in the standard <code>azure/reliability/</code> series) and the AVS <strong>Security, governance, and compliance</strong> scenario guide (a Cloud Adoption Framework page, not a WAF pillar page, but the closest thing Microsoft publishes to a numbered AVS security/governance checklist).</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th><th>Pillar coverage</th></tr></thead><tbody><tr><td><a href="https://learn.microsoft.com/en-us/azure/reliability/reliability-vmware-solution" target="_blank" rel="noreferrer">Reliability in Azure VMware Solution</a></td><td>Azure Reliability documentation series (not WAF-branded, but pillar-aligned)</td><td>Reliability</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/scenarios/azure-vmware/eslz-security-governance-and-compliance" target="_blank" rel="noreferrer">Security, governance, and compliance for Azure VMware Solution</a></td><td>Cloud Adoption Framework scenario guide</td><td>Security + Governance (no WAF equivalent for Cost Optimization, Operational Excellence, or Performance Efficiency was located)</td></tr><tr><td>Framework version</td><td>n/a — see above; this is not the WAF pillar structure</td><td>—</td></tr><tr><td>Extraction date</td><td>2026-08-01</td><td></td></tr><tr><td>Verification method</td><td>Both pages fetched in full via the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool. Every bulleted recommendation under each named subsection is transcribed below, grouped by the subsection heading Microsoft used (not by WAF pillar, since only Reliability genuinely maps to one).</td><td></td></tr></tbody></table><h2 id="what-this-enumeration-is-not-stated-plainly" tabindex="-1">What this enumeration is NOT, stated plainly <a class="header-anchor" href="#what-this-enumeration-is-not-stated-plainly" aria-label="Permalink to &quot;What this enumeration is NOT, stated plainly&quot;">​</a></h2><ul><li><strong>Not the WAF Cost Optimization, Operational Excellence, or Performance Efficiency pillars for AVS.</strong> No published Microsoft content for those pillars, specific to AVS, was located in this pass. This is the largest gap of the four checklists in this release.</li><li><strong>Not the interactive assessment tool&#39;s questions.</strong> As with the other three checklists, the tool itself doesn&#39;t publish its question text.</li><li><strong>Not Item #7 in the audit&#39;s programme</strong> (Azure VMware Solution Landing Zone Assessment Review) — that is a distinct, ninth target in the audit&#39;s list and out of scope for this file, though the Security/Governance source below overlaps with landing-zone content because AVS&#39;s CAF scenario guide doesn&#39;t cleanly separate workload concerns from platform concerns the way the Azure Local guide does.</li></ul><p><strong>Shelf life.</strong> Given that the primary WAF-branded URL for this workload no longer resolves to AVS-specific content, re-verify this enumeration before every future use, not just periodically.</p><h2 id="the-enumeration-—-27-items-across-2-areas" tabindex="-1">The enumeration — 27 items across 2 areas <a class="header-anchor" href="#the-enumeration-—-27-items-across-2-areas" aria-label="Permalink to &quot;The enumeration — 27 items across 2 areas&quot;">​</a></h2><h3 id="reliability-waf-avs-re-—-8-items" tabindex="-1">Reliability (WAF-AVS-RE) — 8 items <a class="header-anchor" href="#reliability-waf-avs-re-—-8-items" aria-label="Permalink to &quot;Reliability (WAF-AVS-RE) — 8 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/en-us/azure/reliability/reliability-vmware-solution" target="_blank" rel="noreferrer">Reliability in Azure VMware Solution</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AVS-RE-01</td><td>vSphere HA is enabled to restart VMs on healthy hosts after a host failure</td><td>❌ Unanswerable — vSphere-internal HA configuration state isn&#39;t exposed via ARM/ARG</td></tr><tr><td>WAF-AVS-RE-02</td><td>vSAN fault tolerance policies protect against storage-level transient faults</td><td>❌ Unanswerable — vSAN storage-policy configuration is inside the private cloud, not ARM-readable</td></tr><tr><td>WAF-AVS-RE-03</td><td>Applications handle transient faults with retry/circuit-breaker patterns</td><td>❌ Unanswerable — application-code pattern</td></tr><tr><td>WAF-AVS-RE-04</td><td>The private cloud uses a zonal or stretched-cluster deployment for availability-zone resilience</td><td>✅ <code>Compute/VMWare</code> — zone/stretched-cluster configuration is an ARM property on the private cloud resource</td></tr><tr><td>WAF-AVS-RE-05</td><td>Minimum host counts are met for the chosen resiliency configuration (for example, six hosts across two zones for a Gen 1 stretched cluster)</td><td>✅ <code>Compute/VMWare</code> — cluster/host count is collected</td></tr><tr><td>WAF-AVS-RE-06</td><td>Multi-region resilience is achieved via separate private clouds with a documented DR solution, where business requirements need it</td><td>⚠️ Partial — Scout can detect multiple <code>Compute/VMWare</code> private clouds across regions/subscriptions; whether they&#39;re deliberately paired for DR isn&#39;t collected</td></tr><tr><td>WAF-AVS-RE-07</td><td>Management-component backups (vCenter Server, NSX Manager, HCX Manager) and workload VM backups are both in place</td><td>⚠️ Partial — management-component backup is Microsoft-managed and not collected; workload VM backup is visible via <code>Management/RecoveryVault</code>, <code>Management/BackupInstances</code> where Azure Backup is used</td></tr><tr><td>WAF-AVS-RE-08</td><td>Maintenance windows are configured to reduce production impact from platform maintenance</td><td>❌ Unanswerable — maintenance-window configuration isn&#39;t in the current <code>Compute/VMWare</code> field set</td></tr></tbody></table><h3 id="security-waf-avs-sec-—-11-items" tabindex="-1">Security (WAF-AVS-SEC) — 11 items <a class="header-anchor" href="#security-waf-avs-sec-—-11-items" aria-label="Permalink to &quot;Security (WAF-AVS-SEC) — 11 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/scenarios/azure-vmware/eslz-security-governance-and-compliance" target="_blank" rel="noreferrer">Security, governance, and compliance for Azure VMware Solution</a> — <strong>Security</strong> section</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AVS-SEC-01</td><td>Permanent Contributor access to the AVS resource group is limited (PIM, time-bound, justification-based)</td><td>❌ Unanswerable — <code>Identity/ConditionalAccess</code> and PIM eligibility aren&#39;t the same collected surface as scoped RG role assignments</td></tr><tr><td>WAF-AVS-SEC-02</td><td><code>cloudadmin</code>/network-admin built-in accounts are centrally managed and used only in break-glass scenarios, with domain-services-sourced accounts for routine access</td><td>❌ Unanswerable — vCenter/NSX-T-internal RBAC configuration, not ARM-readable</td></tr><tr><td>WAF-AVS-SEC-03</td><td>Guest VM identity uses centralized AD DS/LDAP, integrated with Microsoft Entra ID</td><td>⚠️ Partial — <code>Identity/*</code> collectors evidence Entra-side configuration; guest-VM domain-join state isn&#39;t collected</td></tr><tr><td>WAF-AVS-SEC-04</td><td>Network security controls are implemented — traffic filtering, WAF/OWASP compliance, unified firewall management, DDoS protection</td><td>⚠️ Partial — <code>Networking/*</code> collectors (Azure Firewall, WAF policy, DDoS protection plan) evidence the Azure-side controls; NSX-T-internal filtering isn&#39;t collected</td></tr><tr><td>WAF-AVS-SEC-05</td><td>vSAN datastores use customer-managed key (CMK) encryption via Key Vault</td><td>⚠️ Partial — <code>Security/KeyVaultKeys</code> shows CMK material exists; whether it&#39;s bound to the AVS vSAN datastore isn&#39;t collected</td></tr><tr><td>WAF-AVS-SEC-06</td><td>vCenter Server access is via a dedicated privileged access workstation (PAW)</td><td>❌ Unanswerable — an access-pattern practice</td></tr><tr><td>WAF-AVS-SEC-07</td><td>Inbound and outbound internet traffic to/from guest workloads is logged and monitored (SIEM integration)</td><td>⚠️ Partial — <code>Monitor/*</code> and <code>Security/DefenderAlerts</code> evidence logging infrastructure exists generally; AVS-specific traffic-logging configuration isn&#39;t collected</td></tr><tr><td>WAF-AVS-SEC-08</td><td>Backups are centrally managed with RBAC and delayed-delete/soft-delete protection</td><td>✅ <code>Management/RecoveryVault</code> (soft-delete state), <code>Management/BackupInstances</code></td></tr><tr><td>WAF-AVS-SEC-09</td><td>Guest VMs use advanced threat detection (Defender for Cloud, Arc-enabled servers)</td><td>✅ <code>Security/DefenderPricing</code>, <code>Hybrid/ARCServers</code> (where AVS guest VMs are Arc-onboarded)</td></tr><tr><td>WAF-AVS-SEC-10</td><td>Guest VM OS and database encryption is enabled where sensitivity requires it</td><td>❌ Unanswerable — guest-OS-level encryption state isn&#39;t ARM-readable</td></tr><tr><td>WAF-AVS-SEC-11</td><td>Code/DevOps workflows for AVS-hosted workloads use modern auth (OAuth/OpenID Connect)</td><td>❌ Unanswerable — application/pipeline configuration, not an AVS resource property</td></tr></tbody></table><h3 id="governance-waf-avs-gov-—-8-items" tabindex="-1">Governance (WAF-AVS-GOV) — 8 items <a class="header-anchor" href="#governance-waf-avs-gov-—-8-items" aria-label="Permalink to &quot;Governance (WAF-AVS-GOV) — 8 items&quot;">​</a></h3><p>Source: same page — <strong>Governance</strong> section (Environment governance + Workload application and VM governance subsections)</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AVS-GOV-01</td><td>vSAN datastore utilization is monitored with alerts on the Percentage Datastore Disk Used metric</td><td>⚠️ Partial — <code>Monitor/MetricAlertRules</code> can show an alert rule exists if scoped to the AVS private cloud; the specific metric target isn&#39;t distinguished</td></tr><tr><td>WAF-AVS-GOV-02</td><td>VM templates use thin-provisioned storage policies rather than the thick-provisioned default</td><td>❌ Unanswerable — vSAN storage-policy configuration, not ARM-readable</td></tr><tr><td>WAF-AVS-GOV-03</td><td>Host quota is sized ahead of growth/DR needs, with periodic review</td><td>❌ Unanswerable — a capacity-planning practice</td></tr><tr><td>WAF-AVS-GOV-04</td><td>Failure-to-tolerate (FTT) vSAN settings match the cluster size for SLA compliance</td><td>❌ Unanswerable — vSAN-internal storage policy</td></tr><tr><td>WAF-AVS-GOV-05</td><td>Service Health alerts are configured for AVS service issues, planned maintenance, and advisories</td><td>✅ <code>Monitor/ActivityLogAlertRules</code> scoped to the AVS resource, where configured</td></tr><tr><td>WAF-AVS-GOV-06</td><td>Cost governance is in place — budgets, cost alerts, cost allocation for AVS spend</td><td>⚠️ Partial — Cost Management budget collectors exist generally in Scout; AVS-node-specific cost allocation isn&#39;t a distinct collected field</td></tr><tr><td>WAF-AVS-GOV-07</td><td>Azure PaaS services consumed by AVS workloads use private endpoints rather than public endpoints</td><td>✅ <code>Networking/PrivateEndpoint</code></td></tr><tr><td>WAF-AVS-GOV-08</td><td>Workload VMs are onboarded to Azure Arc for policy, update, and tag management parity with native Azure resources</td><td>✅ <code>Hybrid/ARCServers</code></td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Items</th><th>Answerable (✅)</th><th>Partial (⚠️)</th><th>Unanswerable (❌)</th></tr></thead><tbody><tr><td>Reliability</td><td>8</td><td>2</td><td>2</td><td>4</td></tr><tr><td>Security</td><td>11</td><td>2</td><td>4</td><td>5</td></tr><tr><td>Governance</td><td>8</td><td>3</td><td>2</td><td>3</td></tr><tr><td><strong>Total</strong></td><td><strong>27</strong></td><td><strong>7</strong></td><td><strong>8</strong></td><td><strong>12</strong></td></tr></tbody></table><p>7 of 27 items (26%) map cleanly to an existing collector. This is the weakest-covered of the four checklists in this release, for two compounding reasons: much of what makes an AVS deployment well-architected lives inside vCenter/NSX-T/vSAN configuration that Azure Resource Graph cannot see at all (12 of 27 items are unanswerable for exactly this reason), and — unlike the other three workloads — there is no published Cost Optimization, Operational Excellence, or Performance Efficiency source to enumerate in the first place.</p><h2 id="what-this-means-for-the-rule-file" tabindex="-1">What this means for the rule file <a class="header-anchor" href="#what-this-means-for-the-rule-file" aria-label="Permalink to &quot;What this means for the rule file&quot;">​</a></h2><p>A future <code>waf.avs.yaml</code> should cite <code>WAF-AVS-*</code> item numbers and should not claim WAF-pillar coverage it doesn&#39;t have — the honest framing is &quot;Reliability, Security, and Governance coverage for AVS,&quot; not &quot;the AVS Well-Architected Review.&quot; Closing the Cost Optimization / Operational Excellence / Performance Efficiency gap is a prerequisite follow-up task: either a working <code>aka.ms/avswafdocs</code> mirror surfaces published text in a future Microsoft docs pass, or Scout accepts partial-pillar coverage for this workload and says so in the report, the way this file does.</p>',28)])])}const p=t(i,[["render",n]]);export{m as __pageData,p as default};
